-- Nihongo Labs N5 starter content + plans. SAFE, additive and re-runnable.
-- Run only after the existing Nihongo Labs schema has been applied.
-- This file inserts into existing tables; it does not create/alter/drop schema objects.
begin;
values ('nihongo-n5-foundations','JLPT N5 Foundations','A clear path from kana to confident beginner Japanese','A structured beginner course covering kana, grammar, vocabulary, kanji and reading.', 'N5','free','published', '["Read and write basic kana","Understand essential N5 grammar","Build everyday vocabulary","Recognise common N5 kanji","Read short beginner passages"]'::jsonb, 900, 1, now())
on conflict (slug) do update set title=excluded.title,subtitle=excluded.subtitle,description=excluded.description,jlpt_level=excluded.jlpt_level,access_level=excluded.access_level,publication_status='published',learning_outcomes=excluded.learning_outcomes,estimated_duration_minutes=excluded.estimated_duration_minutes,sort_order=excluded.sort_order,published_at=coalesce(public.courses.published_at,now()),updated_at=now();
-- Grammar points
-- Vocabulary entries
-- Kanji entries (starter set; readings should be reviewed by a Japanese-language editor before public launch)
-- Link starter resources to their lessons.
select l.id,g.id,row_number() over(order by g.title)-1 from public.lessons l join public.course_units u on u.id=l.unit_id join public.courses c on c.id=u.course_id cross join public.grammar_points g where c.slug='nihongo-n5-foundations' and l.slug='particles' and g.jlpt_level='N5' on conflict do nothing;
select l.id,v.id,row_number() over(order by v.word)-1 from public.lessons l join public.course_units u on u.id=l.unit_id join public.courses c on c.id=u.course_id cross join public.vocabulary_entries v where c.slug='nihongo-n5-foundations' and l.slug='everyday-words' and v.jlpt_level='N5' on conflict do nothing;
select l.id,k.id,row_number() over(order by k.character)-1 from public.lessons l join public.course_units u on u.id=l.unit_id join public.courses c on c.id=u.course_id cross join public.kanji_entries k where c.slug='nihongo-n5-foundations' and l.slug='first-kanji' and k.jlpt_level='N5' on conflict do nothing;
