select d.id,'vocabulary',v.id,v.word,v.meaning,v.kana,v.romaji,v.example_sentence,v.example_translation,row_number() over(order by v.word)::int,true
from public.flashcard_decks d cross join public.vocabulary_entries v
where d.slug='n5-core-vocabulary' and v.jlpt_level='N5' and v.publication_status='published'
and not exists (select 1 from public.flashcards f where f.deck_id=d.id and f.source_type='vocabulary' and f.vocabulary_id=v.id);
select d.id,'kanji',k.id,k.character,k.meaning,concat('On: ',array_to_string(k.on_yomi,', '),' · Kun: ',array_to_string(k.kun_yomi,', ')),null,k.mnemonic,coalesce(k.example_words->0->>'word',''),coalesce(k.example_words->0->>'meaning',''),row_number() over(order by k.character)::int,true
from public.flashcard_decks d cross join public.kanji_entries k
where d.slug='n5-kanji-basics' and k.jlpt_level='N5' and k.publication_status='published'
and not exists (select 1 from public.flashcards f where f.deck_id=d.id and f.source_type='kanji' and f.kanji_id=k.id);
select d.id,'grammar',g.id,g.pattern,g.title,null,null,g.explanation,coalesce(g.examples->0->>'japanese',''),coalesce(g.examples->0->>'meaning',''),row_number() over(order by g.title)::int,true
from public.flashcard_decks d cross join public.grammar_points g
where d.slug='n5-grammar-patterns' and g.jlpt_level='N5' and g.publication_status='published'
and not exists (select 1 from public.flashcards f where f.deck_id=d.id and f.source_type='grammar' and f.grammar_id=g.id);

-- Sentence construction: a server-graded ordering question in the daily practice set.
with quiz_row as (select id from public.quizzes where slug='n5-daily-practice'),
qrow as (
  select id,'ordering'::public.quiz_question_type,
    '{"text":"Build the sentence: I study Japanese every day.","instruction":"Tap the tiles in the correct Japanese word order.","meaning":"Every day, I study Japanese."}'::jsonb,
    2,6,true from quiz_row
  on conflict (quiz_id,sort_order) do update set
    question_type=excluded.question_type,prompt=excluded.prompt,points=excluded.points,is_active=true,updated_at=now()
  returning id
)
select id,'{"sequence":["A","B","C","D"]}'::jsonb,
  '{"explanation":"A simple Japanese sentence commonly places the topic first, then a time phrase, then the object, and the verb at the end.","example":"わたしは毎日日本語を勉強します。","translation":"I study Japanese every day."}'::jsonb
from qrow
on conflict (question_id) do update set answer_key=excluded.answer_key,explanation=excluded.explanation;
select qq.id,x.option_key,x.option_content::jsonb,x.sort_order
from public.quiz_questions qq
join public.quizzes qz on qz.id=qq.quiz_id
cross join (values
  ('A','{"text":"わたしは"}',1),
  ('B','{"text":"毎日"}',2),
  ('C','{"text":"日本語を"}',3),
  ('D','{"text":"勉強します。"}',4)
) as x(option_key,option_content,sort_order)
where qz.slug='n5-daily-practice' and qq.sort_order=6
on conflict (question_id,option_key) do update set option_content=excluded.option_content,sort_order=excluded.sort_order;

-- Free, Basic and Plus plan catalog. Razorpay plan IDs remain NULL until configured in the merchant account.
on conflict (code) do update set name=excluded.name,description=excluded.description,plan_kind=excluded.plan_kind,amount_minor=excluded.amount_minor,currency=excluded.currency,billing_interval=excluded.billing_interval,interval_count=excluded.interval_count,is_active=true,display_order=excluded.display_order,updated_at=now();
select p.id,x.feature_key,x.feature_value from public.subscription_plans p cross join (values
('free','kana_access','true'::jsonb),('free','selected_grammar','true'::jsonb),('free','daily_practice','true'::jsonb),('free','basic_progress','true'::jsonb),
('basic_monthly','full_grammar','true'::jsonb),('basic_monthly','vocabulary_revision','true'::jsonb),('basic_monthly','kanji_revision','true'::jsonb),('basic_monthly','daily_progress','true'::jsonb),
('plus_monthly','full_grammar','true'::jsonb),('plus_monthly','vocabulary_revision','true'::jsonb),('plus_monthly','kanji_revision','true'::jsonb),('plus_monthly','flashcards','true'::jsonb),('plus_monthly','reading','true'::jsonb),('plus_monthly','mock_exams','true'::jsonb),('plus_monthly','premium_content','true'::jsonb)
) as x(plan_code,feature_key,feature_value) where p.code=x.plan_code on conflict (plan_id,feature_key) do update set feature_value=excluded.feature_value;
commit;
