insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Topic marker は','N は','Marks the topic of a sentence; it is commonly pronounced wa.','N は ... です','[{"japanese":"わたしは学生です。","romaji":"Watashi wa gakusei desu.","meaning":"I am a student."},{"japanese":"これは本です。","romaji":"Kore wa hon desu.","meaning":"This is a book."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Subject marker が','N が','Marks the grammatical subject or highlights new information.','N が ...','[{"japanese":"ねこがいます。","romaji":"Neko ga imasu.","meaning":"There is a cat."},{"japanese":"だれが来ますか。","romaji":"Dare ga kimasu ka.","meaning":"Who is coming?"}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Object marker を','N を V','Marks the direct object of an action.','N を V','[{"japanese":"水を飲みます。","romaji":"Mizu o nomimasu.","meaning":"I drink water."},{"japanese":"本を読みます。","romaji":"Hon o yomimasu.","meaning":"I read a book."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Destination に','Place に 行きます','Marks a destination or a specific time.','Place に 行きます','[{"japanese":"学校に行きます。","romaji":"Gakkou ni ikimasu.","meaning":"I go to school."},{"japanese":"七時に起きます。","romaji":"Shichi-ji ni okimasu.","meaning":"I get up at seven."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Place of action で','Place で V','Marks where an action takes place.','Place で V','[{"japanese":"図書館で勉強します。","romaji":"Toshokan de benkyou shimasu.","meaning":"I study at the library."},{"japanese":"家で食べます。","romaji":"Ie de tabemasu.","meaning":"I eat at home."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Possessive の','N1 の N2','Connects nouns and often shows possession or description.','N1 の N2','[{"japanese":"これはわたしのかばんです。","romaji":"Kore wa watashi no kaban desu.","meaning":"This is my bag."},{"japanese":"日本語の本です。","romaji":"Nihongo no hon desu.","meaning":"It is a Japanese book."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Direction へ','Place へ 行きます','Marks the direction of movement; pronounced e.','Place へ 行きます','[{"japanese":"日本へ行きます。","romaji":"Nihon e ikimasu.","meaning":"I am going to Japan."},{"japanese":"駅へ歩きます。","romaji":"Eki e arukimasu.","meaning":"I walk toward the station."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','And / listing と','N と N','Connects nouns in a complete list.','N と N','[{"japanese":"友だちと話します。","romaji":"Tomodachi to hanashimasu.","meaning":"I talk with a friend."},{"japanese":"パンと牛乳を買います。","romaji":"Pan to gyuunyuu o kaimasu.","meaning":"I buy bread and milk."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Also も','N も','Means also or too, replacing は or が in many simple sentences.','N も ...','[{"japanese":"わたしも学生です。","romaji":"Watashi mo gakusei desu.","meaning":"I am a student too."},{"japanese":"田中さんも来ます。","romaji":"Tanaka-san mo kimasu.","meaning":"Mr./Ms. Tanaka is coming too."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','です','N / な-adjective です','A polite sentence ending used to make statements.','N です','[{"japanese":"わたしは会社員です。","romaji":"Watashi wa kaishain desu.","meaning":"I am an office worker."},{"japanese":"この町は静かです。","romaji":"Kono machi wa shizuka desu.","meaning":"This town is quiet."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Negative じゃありません','N じゃありません','Polite negative form of a noun sentence.','N じゃありません','[{"japanese":"学生じゃありません。","romaji":"Gakusei ja arimasen.","meaning":"I am not a student."},{"japanese":"これは水じゃありません。","romaji":"Kore wa mizu ja arimasen.","meaning":"This is not water."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Question か','Sentence か','Turns a statement into a polite question.','Sentence + か','[{"japanese":"田中さんは先生ですか。","romaji":"Tanaka-san wa sensei desu ka.","meaning":"Is Tanaka a teacher?"},{"japanese":"これは何ですか。","romaji":"Kore wa nan desu ka.","meaning":"What is this?"}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Past tense でした','N でした','Past polite form of a noun sentence.','N でした','[{"japanese":"きのうは休みでした。","romaji":"Kinou wa yasumi deshita.","meaning":"Yesterday was a day off."},{"japanese":"学生でした。","romaji":"Gakusei deshita.","meaning":"I was a student."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Verb polite present ます','V-ます','Polite non-past verb form for present habits and future actions.','Verb stem + ます','[{"japanese":"毎日勉強します。","romaji":"Mainichi benkyou shimasu.","meaning":"I study every day."},{"japanese":"朝ごはんを食べます。","romaji":"Asagohan o tabemasu.","meaning":"I eat breakfast."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Verb negative ません','V-ません','Polite negative form of a verb.','Verb stem + ません','[{"japanese":"コーヒーを飲みません。","romaji":"Koohii o nomimasen.","meaning":"I do not drink coffee."},{"japanese":"今日は行きません。","romaji":"Kyou wa ikimasen.","meaning":"I am not going today."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Verb past ました','V-ました','Polite past form of a verb.','Verb stem + ました','[{"japanese":"昨日映画を見ました。","romaji":"Kinou eiga o mimashita.","meaning":"I watched a movie yesterday."},{"japanese":"朝パンを食べました。","romaji":"Asa pan o tabemashita.","meaning":"I ate bread in the morning."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Verb past negative ませんでした','V-ませんでした','Polite negative past form of a verb.','Verb stem + ませんでした','[{"japanese":"テレビを見ませんでした。","romaji":"Terebi o mimasen deshita.","meaning":"I did not watch television."},{"japanese":"学校へ行きませんでした。","romaji":"Gakkou e ikimasen deshita.","meaning":"I did not go to school."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Existence あります / います','N が あります / います','あります is used for things; います is used for people and animals.','Thing が あります / Person が います','[{"japanese":"つくえの上に本があります。","romaji":"Tsukue no ue ni hon ga arimasu.","meaning":"There is a book on the desk."},{"japanese":"部屋にねこがいます。","romaji":"Heya ni neko ga imasu.","meaning":"There is a cat in the room."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Adjective past かったです','い-adjective かったです','Polite past form of an i-adjective.','Remove い + かったです','[{"japanese":"昨日は暑かったです。","romaji":"Kinou wa atsukatta desu.","meaning":"It was hot yesterday."},{"japanese":"この本はおもしろかったです。","romaji":"Kono hon wa omoshirokatta desu.","meaning":"This book was interesting."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Want to do たいです','V-たいです','Expresses what the speaker wants to do.','Verb stem + たいです','[{"japanese":"日本へ行きたいです。","romaji":"Nihon e ikitai desu.","meaning":"I want to go to Japan."},{"japanese":"水を飲みたいです。","romaji":"Mizu o nomitai desu.","meaning":"I want to drink water."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Please てください','V-てください','A polite request meaning please do something.','V-て + ください','[{"japanese":"ここに名前を書いてください。","romaji":"Koko ni namae o kaite kudasai.","meaning":"Please write your name here."},{"japanese":"ゆっくり話してください。","romaji":"Yukkuri hanashite kudasai.","meaning":"Please speak slowly."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','May I てもいいです','V-てもいいです','Asks or states that an action is permitted.','V-てもいいです','[{"japanese":"ここに座ってもいいですか。","romaji":"Koko ni suwatte mo ii desu ka.","meaning":"May I sit here?"},{"japanese":"写真を撮ってもいいです。","romaji":"Shashin o totte mo ii desu.","meaning":"You may take a photo."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Must not てはいけません','V-てはいけません','Expresses prohibition: must not do something.','V-てはいけません','[{"japanese":"ここで食べてはいけません。","romaji":"Koko de tabete wa ikemasen.","meaning":"You must not eat here."},{"japanese":"ここに入ってはいけません。","romaji":"Koko ni haitte wa ikemasen.","meaning":"You must not enter here."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Because から','Reason から, result','Gives a reason or cause.','Reason + から','[{"japanese":"雨ですから、行きません。","romaji":"Ame desu kara, ikimasen.","meaning":"Because it is raining, I will not go."},{"japanese":"忙しいですから、あとで話します。","romaji":"Isogashii desu kara, ato de hanashimasu.","meaning":"Because I am busy, I will talk later."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Comparison より','A は B より ...','Compares two things using yori for the standard.','A は B より adjective','[{"japanese":"今日は昨日より暑いです。","romaji":"Kyou wa kinou yori atsui desu.","meaning":"Today is hotter than yesterday."},{"japanese":"犬はねこより大きいです。","romaji":"Inu wa neko yori ookii desu.","meaning":"Dogs are bigger than cats."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
insert into public.grammar_points (jlpt_level,title,pattern,explanation,formation,examples,common_mistakes,publication_status) values ('N5','Approximation ぐらい','Number + ぐらい','Means approximately or about.','Number + ぐらい','[{"japanese":"三十分ぐらい勉強します。","romaji":"Sanjuppun gurai benkyou shimasu.","meaning":"I study for about thirty minutes."},{"japanese":"五人ぐらい来ます。","romaji":"Gonin gurai kimasu.","meaning":"About five people will come."}]'::jsonb,'["Check which part of the sentence the particle connects.","Use the polite ending consistently."]'::jsonb,'published') on conflict (jlpt_level,pattern) do update set title=excluded.title,explanation=excluded.explanation,formation=excluded.formation,examples=excluded.examples,common_mistakes=excluded.common_mistakes,publication_status='published',updated_at=now();
