insert into public.lesson_content_blocks (lesson_id,block_type,access_level,content,sort_order) select l.id,'rich_text','free','{"kind":"reading_passage","title":"A day at school","text":"わたしは学生です。毎日、七時に起きます。八時に学校へ行きます。学校で日本語を勉強します。","romaji":"Watashi wa gakusei desu. Mainichi, shichi-ji ni okimasu. Hachi-ji ni gakkou e ikimasu. Gakkou de nihongo o benkyou shimasu.","translation":"I am a student. I get up at seven every day. I go to school at eight. I study Japanese at school.","vocabulary":[{"word":"毎日","reading":"まいにち","romaji":"mainichi","meaning":"every day"},{"word":"起きます","reading":"おきます","romaji":"okimasu","meaning":"get up"},{"word":"学校","reading":"がっこう","romaji":"gakkou","meaning":"school"}]}'::jsonb,2 from public.lessons l join public.course_units u on u.id=l.unit_id join public.courses c on c.id=u.course_id where c.slug='nihongo-n5-foundations' and l.slug='short-passages' on conflict (lesson_id,sort_order) do update set content=excluded.content,block_type='rich_text',access_level='free',updated_at=now();
insert into public.lesson_content_blocks (lesson_id,block_type,access_level,content,sort_order) select l.id,'rich_text','free','{"kind":"reading_passage","title":"My friend and tea","text":"田中さんはわたしの友だちです。田中さんは日本語の先生です。土曜日に、いっしょにお茶を飲みます。","romaji":"Tanaka-san wa watashi no tomodachi desu. Tanaka-san wa nihongo no sensei desu. Doyoubi ni, issho ni ocha o nomimasu.","translation":"Mr./Ms. Tanaka is my friend. Tanaka is a Japanese teacher. On Saturday, we drink tea together.","vocabulary":[{"word":"友だち","reading":"ともだち","romaji":"tomodachi","meaning":"friend"},{"word":"先生","reading":"せんせい","romaji":"sensei","meaning":"teacher"},{"word":"土曜日","reading":"どようび","romaji":"doyoubi","meaning":"Saturday"}]}'::jsonb,3 from public.lessons l join public.course_units u on u.id=l.unit_id join public.courses c on c.id=u.course_id where c.slug='nihongo-n5-foundations' and l.slug='short-passages' on conflict (lesson_id,sort_order) do update set content=excluded.content,block_type='rich_text',access_level='free',updated_at=now();
